<?php
namespace App\Services;
use App\Models\{DetailStokMasuk,Notifikasi,RiwayatStok,Sparepart,StokMasuk,User};
use Illuminate\Support\Facades\DB;
use RuntimeException;

class InventoryService {
    public function actorPetugasId(?int $userId): ?int { return DB::table('petugas')->where('id_user',$userId)->value('id_petugas') ?: DB::table('petugas')->where('status','aktif')->value('id_petugas'); }
    public function createReceipt(array $data, int $petugasId): StokMasuk { return DB::transaction(function() use($data,$petugasId){ $code='SM-'.now()->format('YmdHis').'-'.random_int(100,999); while(StokMasuk::where('kode_stok_masuk',$code)->exists()) $code='SM-'.now()->format('YmdHis').'-'.random_int(100,999); return StokMasuk::create(['kode_stok_masuk'=>$code,'id_supplier'=>$data['id_supplier']??null,'id_petugas'=>$petugasId,'tanggal'=>$data['tanggal'],'status'=>'draft','catatan'=>$data['catatan']??'','total_biaya'=>0]); }); }
    private function draft(int $id): StokMasuk { $r=StokMasuk::lockForUpdate()->findOrFail($id); if($r->status!=='draft') throw new RuntimeException('Dokumen sudah tidak berstatus draft.'); return $r; }
    private function subtotal(string $price,int $qty): string { return (string)DB::selectOne('SELECT CAST(? * ? AS DECIMAL(15,2)) AS value',[$price,$qty])->value; }
    private function recalc(StokMasuk $r): void { $r->update(['total_biaya'=>DetailStokMasuk::where('id_stok_masuk',$r->id_stok_masuk)->sum('subtotal')]); }
    public function addDetail(int $receiptId,array $data): DetailStokMasuk { return DB::transaction(function() use($receiptId,$data){ $r=$this->draft($receiptId); if(DetailStokMasuk::where('id_stok_masuk',$r->id_stok_masuk)->where('id_sparepart',$data['id_sparepart'])->exists()) throw new RuntimeException('Spare part sudah ada di draft.'); $d=DetailStokMasuk::create(['id_stok_masuk'=>$r->id_stok_masuk,'id_sparepart'=>$data['id_sparepart'],'jumlah'=>$data['jumlah'],'harga_beli'=>$data['harga_beli'],'subtotal'=>$this->subtotal($data['harga_beli'],$data['jumlah'])]); $this->recalc($r); return $d; }); }
    public function updateDetail(int $detailId,array $data): void { DB::transaction(function() use($detailId,$data){ $d=DetailStokMasuk::lockForUpdate()->findOrFail($detailId); $this->draft($d->id_stok_masuk); $d->update(['jumlah'=>$data['jumlah'],'harga_beli'=>$data['harga_beli'],'subtotal'=>$this->subtotal($data['harga_beli'],$data['jumlah'])]); $this->recalc($d->stokMasuk); }); }
    public function removeDetail(int $detailId): void { DB::transaction(function() use($detailId){ $d=DetailStokMasuk::lockForUpdate()->findOrFail($detailId); $r=$this->draft($d->id_stok_masuk); $d->delete(); $this->recalc($r); }); }
    public function cancel(int $id): void { DB::transaction(function() use($id){ $r=$this->draft($id); $r->update(['status'=>'dibatalkan']); }); }
    public function finalize(int $id): void { DB::transaction(function() use($id){ $r=StokMasuk::lockForUpdate()->findOrFail($id); if($r->status!=='draft') throw new RuntimeException('Dokumen sudah diproses.'); $items=DetailStokMasuk::where('id_stok_masuk',$id)->orderBy('id_sparepart')->get(); if($items->isEmpty()) throw new RuntimeException('Draft belum memiliki item.'); foreach($items as $item){ $s=Sparepart::lockForUpdate()->findOrFail($item->id_sparepart); $before=(int)$s->stok; $after=$before+(int)$item->jumlah; DB::table('sparepart')->where('id_sparepart',$s->id_sparepart)->update(['stok'=>$after]); $s->refresh(); RiwayatStok::create(['id_sparepart'=>$s->id_sparepart,'id_petugas'=>$r->id_petugas,'tanggal'=>now(),'jenis_transaksi'=>'stok_masuk','jumlah_perubahan'=>$item->jumlah,'stok_sebelum'=>$before,'stok_sesudah'=>$after,'referensi_tipe'=>'stok_masuk','referensi_id'=>$id,'catatan'=>'Penerimaan '.$r->kode_stok_masuk]); $this->notify($s,$after,(int)$s->stok_minimum); } $r->update(['status'=>'diterima','total_biaya'=>DetailStokMasuk::where('id_stok_masuk',$id)->sum('subtotal')]); }); }
    public function adjust(int $sparepartId,int $newStock,string $reason,string $note,?int $petugasId): void { DB::transaction(function() use($sparepartId,$newStock,$reason,$note,$petugasId){ $s=Sparepart::lockForUpdate()->findOrFail($sparepartId); $before=(int)$s->stok; DB::table('sparepart')->where('id_sparepart',$s->id_sparepart)->update(['stok'=>$newStock]); $s->refresh(); RiwayatStok::create(['id_sparepart'=>$s->id_sparepart,'id_petugas'=>$petugasId,'tanggal'=>now(),'jenis_transaksi'=>'penyesuaian','jumlah_perubahan'=>$newStock-$before,'stok_sebelum'=>$before,'stok_sesudah'=>$newStock,'referensi_tipe'=>'sparepart','referensi_id'=>$s->id_sparepart,'catatan'=>$reason.' — '.$note]); $this->notify($s,$newStock,(int)$s->stok_minimum); }); }
    private function notify(Sparepart $s,int $stock,int $minimum): void { $admins=User::whereHas('role',fn($q)=>$q->where('nama_role','admin'))->pluck('id_user'); $low=$stock===0?'Stok Spare Part Habis':($stock<=$minimum?'Stok Spare Part Menipis':null); foreach($admins as $uid){ $q=Notifikasi::where('id_user',$uid)->where('referensi_tipe','sparepart')->where('referensi_id',$s->id_sparepart)->where('tipe','stok'); if(!$low){$q->where('is_read',false)->update(['is_read'=>true]); continue;} if(!$q->where('judul',$low)->where('is_read',false)->exists()) Notifikasi::create(['id_user'=>$uid,'judul'=>$low,'pesan'=>$s->nama_sparepart.' memiliki stok '.$stock.' (minimum '.$minimum.').','tipe'=>'stok','referensi_tipe'=>'sparepart','referensi_id'=>$s->id_sparepart,'is_read'=>false]); } }
    public function consumeServicePartsWithinTransaction(iterable $items,int $petugasId,int $serviceId,string $serviceCode): array { $result=[]; foreach(collect($items)->sortBy('id_sparepart') as $item){ $s=Sparepart::lockForUpdate()->findOrFail($item->id_sparepart); $before=(int)$s->stok; $qty=(int)$item->jumlah; if($before<$qty) throw new RuntimeException('Stok tidak cukup untuk seluruh spare part servis.'); $after=$before-$qty; DB::table('sparepart')->where('id_sparepart',$s->id_sparepart)->update(['stok'=>$after]); RiwayatStok::create(['id_sparepart'=>$s->id_sparepart,'id_petugas'=>$petugasId,'tanggal'=>now(),'jenis_transaksi'=>'servis','jumlah_perubahan'=>-$qty,'stok_sebelum'=>$before,'stok_sesudah'=>$after,'referensi_tipe'=>'servis','referensi_id'=>$serviceId,'catatan'=>'Finalisasi '.$serviceCode]); $this->notify($s,$after,(int)$s->stok_minimum); $result[$s->id_sparepart]=[$before,$after]; } return $result; }
    public function consumeSalePartsWithinTransaction(iterable $items,int $petugasId,int $saleId,string $saleCode): array { $result=[]; foreach(collect($items)->sortBy('id_sparepart') as $item){ $s=Sparepart::lockForUpdate()->findOrFail($item->id_sparepart); $before=(int)$s->stok; $qty=(int)$item->jumlah; if($qty<=0||$before<$qty) throw new RuntimeException('Stok tidak cukup untuk seluruh item.'); $after=$before-$qty; DB::table('sparepart')->where('id_sparepart',$s->id_sparepart)->update(['stok'=>$after]); RiwayatStok::create(['id_sparepart'=>$s->id_sparepart,'id_petugas'=>$petugasId,'tanggal'=>now(),'jenis_transaksi'=>'penjualan','jumlah_perubahan'=>-$qty,'stok_sebelum'=>$before,'stok_sesudah'=>$after,'referensi_tipe'=>'penjualan_sparepart','referensi_id'=>$saleId,'catatan'=>'Finalisasi '.$saleCode]); $this->notify($s,$after,(int)$s->stok_minimum); $result[$s->id_sparepart]=[$before,$after]; } return $result; }
}
